class_name();

function class_name(){

   

    let sendingData = {
        "action" : "class_read"
    }

    $.ajax( {
        method: "POST",
        dataType: "JSON",
        url : "../APi/class.php",
        data : sendingData,
        success: function(data){

            let status = data.status;
            let response = data.data;
            let html = '';
            let tr = '';

            if(status){

                
                response.forEach( res => {

                   html += `<option value="${res['class_id']}">${res['class_name']}</option>`;
                })

                $("#class_id").append(html);

              
            }else{
                alert("error",response);
            }
           

        },
        error: function(data){

        }
    })

}



