$("#modal-semester_subject").on("submit",function(event) {

    event.preventDefault();
    console.log(34567);
    let id = $("#update_id").val();
    let class_name = $("#class_id").val();
    let semester_name = $("#semester_id").val();
    let subject_id = $("#subject_id").val();
   
   

    let sendingData = {}

    if(btnAction == "Insert"){
        sendingData = {
             "class_id":class_name,
            "subject_id":subject_id,
            "semester_id" : semester_name,
            "action" :  "register_semester_subject" 
            
        }
    
    }
    else{
          sendingData = { 
            "class_id":class_name,
            "subject_id":subject_id,
            "semester_id" : semester_name,
            "subject_semester_id": id  ,
            "action" : "Update_semester_subject"
            
        }
    
    }

    
  
    $.ajax( {
        method: "POST",
        dataType: "JSON",
        url : "../APi/semester_subject.php",
        data : sendingData,
        success: function(data){

            let status = data.status;
            let response = data.data;

            if(status){

                Swal.fire({
                    title: response,
                    icon: "success"
                  });

                //   setTimeout(() => {
                   
                //     $(".modal-semester_subject").hide();
                //   }, 3000);

                console.log("success",response);
                btnAction = "Insert";
                loadData();
            }else{
                alert("error",response);
            }
           

        },
        error: function(data){
          console.log("error",data);
        }
    })

})


loadData();
function loadData(){

    $("#semester_subject_Table tbody").html('');

    let sendingData = {
        "action" : "semester_subject_read"
    }

    $.ajax( {
        method: "POST",
        dataType: "JSON",
        url : "../APi/semester_subject.php",
        data : sendingData,
        success: function(data){

            let status = data.status;
            let response = data.data;
            let html = '';
            let tr = '';

            if(status){

                response.forEach( itm => {

                    tr += "<tr>";
                    for(let i in itm){

                      
                            tr += `<td>${itm[i]}</td>`;
                        }

                    

                        tr += `<td > <buttonclass="btn_upda"> <a class="updete_cl"update_id=${itm['subject_semester_id']}><span class="material-symbols-outlined" style ="color:#fff;background-color:var(--base-clr); font-size: xx-large;  font-weight: bold; border-radius: 5px; ">edit
                        </span></a></button> &nbsp;&nbsp;<a class="delete_cl" delete_id=${itm['subject_semester_id']}><span class="material-symbols-outlined" style ="color:#fff;background-color:red;font-size: xx-large;  font-weight: bold; border-radius: 5px;">delete
                        </span></a> </td>`              
                       
                        tr += '</tr>'  

                })

                $("#semester_subject_Table tbody").append(tr);

            }else{
                console.log("error",response);
            }
           

        },
        error: function(data){
            console.log(data);

        }
    })

}



function semester_subject_fetch(id){

    let sendingData = {
        "action" : "semester_subject_fetch",
        "subject_semester_id": id   
    }

    $.ajax( {
        method: "POST",
        dataType: "JSON",
     
        url : "../APi/semester_subject.php",
        data : sendingData,
        success: function(data){

            let status = data.status;
            let response = data.data;
            let html = '';
            let tr = '';

            if(status){
            
                btnAction = "Update";
                   $("#update_id").val(response['subject_semester_id']); 
                   $("#class_id").val(response['class_id']);
                   $("#subject_id").val(response['subject_id']);
                   $("#semester_id").val(response['semester_id']);
                   $(".modal-semester_subject").show();

            }else{
                alet("error",response);
            }
           

        },
        error: function(data){

        }
    })



}



function semester_subject_delete(id){

    let sendingData = {
        action : "delete_semester_subject_info",
        "subject_semester_id": id  
    }

    $.ajax( {
        method: "POST",
        dataType: "JSON",
        url : "../APi/semester_subject.php",
        data : sendingData,
        success: function(data){

            let status = data.status;
            let response = data.data;
            let html = '';
            let tr = '';

            if(status){

              
                Swal.fire({
                    title: response,
                    icon: "success"
                  });

                loadData();

            }else{
                alert(response);
            }
           

        },
        error: function(data){

        }
    })



}







